<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
onMounted(() => { const timer = window.setInterval(() => { const sheet = document.querySelector('.tracking-sheet'); const delivered = sheet?.querySelector('.tracking-sheet__heading strong')?.textContent?.trim() === 'Entregado'; sheet?.classList.toggle('is-delivered', delivered) }, 100); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const timer = window.setInterval(() => { const sheet = document.querySelector('.tracking-top-card~.tracking-sheet'); if (!sheet || sheet.querySelector('.tracking-assigned-tabs')) return; expanded.value = false; const tabs = document.createElement('div'); tabs.className = 'tracking-assigned-tabs'; const detail = document.createElement('button'); detail.textContent = 'Detalle del pedido'; detail.addEventListener('click', () => { expanded.value = true }); tabs.append(detail); const content = sheet.querySelector('.tracking-detail'); if (content) sheet.insertBefore(tabs, content); else sheet.append(tabs) }, 100); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const sheet = document.querySelector('.tracking-top-card~.tracking-sheet'); if (!sheet || sheet.querySelector('.tracking-assigned-tabs')) return; expanded.value = false; const tabs = document.createElement('div'); tabs.className = 'tracking-assigned-tabs'; const detail = document.createElement('button'); detail.textContent = 'Detalle del pedido'; detail.addEventListener('click', () => { expanded.value = true }); tabs.append(detail); sheet.insertBefore(tabs, sheet.querySelector('.tracking-detail')) })
onMounted(() => { const timer = window.setInterval(() => { const target = document.querySelector('.tracking-top-card .assigned-topline strong'); if (target && props.routeInfo?.window) target.textContent = props.routeInfo.window }, 200); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const sheet = document.querySelector('.tracking-sheet'); if (!sheet) return; let start = 0; const startDrag = (event) => { start = event.touches?.[0]?.clientY ?? event.clientY }; const endDrag = (event) => { const end = event.changedTouches?.[0]?.clientY ?? event.clientY; if (start - end > 30) expanded.value = true; if (end - start > 30) expanded.value = false }; sheet.addEventListener('touchstart', startDrag, { passive: true }); sheet.addEventListener('touchend', endDrag, { passive: true }); onBeforeUnmount(() => { sheet.removeEventListener('touchstart', startDrag); sheet.removeEventListener('touchend', endDrag) }) })
import { Bike, CheckCircle2, ChevronUp, MapPin, PackageCheck, Truck, XCircle } from 'lucide-vue-next'
import OrderProgressSegments from './OrderProgressSegments.vue'
import '../assets/tracking.css'
import '../assets/tracking-cancellation.css'

const props = defineProps({ order: { type: Object, required: true }, hasCourier: Boolean, routeInfo: { type: Object, default: null } })
const emit = defineEmits(['back'])
const expanded = ref(false); const dragging = ref(false); const startY = ref(0)
const labels = { PENDIENTE_ACEPTACION: 'Esperando confirmación', PREPARANDO: 'Preparando tu pedido', LISTO_PARA_RECOGER: 'Pedido listo', PENDIENTE: 'Esperando confirmación', ASIGNADO: 'Repartidor asignado', RECOGIDO: 'Pedido recogido', EN_CAMINO: 'En camino', ENTREGADO: 'Entregado', CANCELADO: 'Pedido cancelado' }
const now = ref(Date.now()); let timer
const preparationRemaining = computed(() => { if (props.order.estado !== 'PREPARANDO' || !props.order.preparacion_lista_estimada_en) return null; return Math.max(0, Math.ceil((new Date(props.order.preparacion_lista_estimada_en).getTime() - now.value) / 60000)) })
const messages = new Proxy({ ASIGNADO: '', RECOGIDO: 'Tu pedido fue recogido por el repartidor.', EN_CAMINO: 'va hacia tu dirección.', ENTREGADO: 'Tu pedido fue entregado.' }, { get(target, key) { if (key === 'PREPARANDO') { if (preparationRemaining.value == null) return 'Tiempo de preparación pendiente'; return preparationRemaining.value > 0 ? `${preparationRemaining.value} min restantes` : 'Tu pedido está tardando un poco más de lo previsto.' } return target[key] } })
onMounted(() => { timer = window.setInterval(() => { now.value = Date.now() }, 1000) }); onBeforeUnmount(() => window.clearInterval(timer))
const icon = computed(() => props.order.estado === 'CANCELADO' ? XCircle : props.order.estado === 'EN_CAMINO' ? Truck : props.order.estado === 'ENTREGADO' ? CheckCircle2 : MapPin)
const establishmentLabel = computed(() => props.order.restaurantes?.tipo_establecimiento === 'SUPERMERCADO' ? 'El supermercado' : props.order.restaurantes?.tipo_establecimiento === 'FARMACIA' ? 'La farmacia' : 'El restaurante')
const courierName = computed(() => {
  const assignment = props.order.asignaciones?.find((item) => !item.terminada_en)
  const courier = Array.isArray(assignment?.repartidores) ? assignment.repartidores[0] : assignment?.repartidores
  const profile = Array.isArray(courier?.perfiles) ? courier.perfiles[0] : courier?.perfiles
  return props.order.repartidor_nombre || profile?.nombre || courier?.nombre || 'Repartidor asignado'
})
const courierHeadline = computed(() => `¡Yendo! ${courierName.value} está en camino`)
const courierMessage = computed(() => props.order.estado === 'EN_CAMINO' ? `${courierName.value} ${messages.EN_CAMINO}` : messages[props.order.estado] || '')
function toggle() { expanded.value = !expanded.value }
const cancellationReasons = { SIN_REPARTIDORES_EN_AREA: 'No hay repartidores suficientes en el área', SIN_REPARTIDORES: 'No hay repartidores suficientes en el área', CAPACIDAD_SUPERADA: 'La capacidad de repartidores fue superada', ZONA_BLOQUEADA: 'La zona se encuentra bloqueada', RESTAURANTE_RECHAZA: 'El restaurante rechazó el pedido', PRODUCTOS_NO_DISPONIBLES: 'Productos no disponibles', PROBLEMAS_DE_ENTREGA: 'Problemas de entrega', SOLICITUD_CLIENTE: 'Solicitud del cliente', CAMBIO_DE_OPINION: 'Cambio de opinión', ERROR_EN_PEDIDO: 'Error en el pedido', DIRECCION_INCORRECTA: 'Dirección incorrecta', DEMORA_EN_PEDIDO: 'Demora en el pedido', OTRO: 'Otro' }
function cancellationReason(code, description) { if (cancellationReasons[code]) return cancellationReasons[code]; if (description?.trim()) return description.trim(); if (code) return code.replaceAll('_', ' ').toLowerCase().replace(/^./, (letter) => letter.toUpperCase()); return 'Motivo no especificado' }
function refundLabel(order) { if (order.estado_pago === 'CANCELADO_SIN_COBRO') return 'No se realizó ningún cobro.'; const refund = order.reembolsos?.[0]; if (!refund) return 'No hay una devolución asociada.'; if (refund.estado === 'SIMULADO_COMPLETADO') return `Devolución completada por $${Number(refund.monto || 0).toFixed(2)}.`; if (refund.estado === 'REVISION_MANUAL') return 'Devolución pendiente de revisión administrativa.'; if (refund.estado === 'REVISION_APROBADA') return 'Devolución aprobada; aún no se registra como dinero devuelto.'; if (refund.estado === 'REVISION_RECHAZADA') return 'Solicitud de devolución rechazada.'; return 'Devolución pendiente.' }
function refundStage(order) { const refund = order.reembolsos?.[0]; if (order.estado_pago === 'CANCELADO_SIN_COBRO' || !refund) return []; return refund.estado === 'SIMULADO_COMPLETADO' ? ['Pedido cancelado', 'Devolución solicitada', 'Devolución completada'] : refund.estado === 'REVISION_MANUAL' ? ['Pedido cancelado', 'Devolución solicitada', 'En revisión administrativa'] : refund.estado === 'REVISION_APROBADA' ? ['Pedido cancelado', 'Devolución solicitada', 'Aprobación registrada'] : ['Pedido cancelado', 'Devolución solicitada', 'Solicitud rechazada'] }
function formatRefundDate(value) { return value ? new Date(value).toLocaleString('es-SV') : '—' }
function down(event) { dragging.value = true; startY.value = event.touches[0].clientY }
function up(event) { if (!dragging.value) return; const delta = event.changedTouches[0].clientY - startY.value; if (Math.abs(delta) > 30) expanded.value = delta < 0; dragging.value = false }
</script>

<template>
  <div class="tracking-layout">
    <Transition name="tracking-top-card"><section v-if="hasCourier" class="tracking-top-card"><div class="assigned-topline"><span>A tiempo</span><strong v-if="routeInfo?.min != null">{{ routeInfo.min.toFixed(0) }} min estimados</strong><small v-if="routeInfo?.min != null">{{ order.estado === 'ASIGNADO' ? 'Llegada estimada al restaurante' : 'Llegada estimada de tu pedido' }}</small><strong v-else>Tiempo no disponible</strong><Bike class="assigned-bike" :size="54" /></div><div class="assigned-heading"><div><strong>{{ courierHeadline }}</strong><p>{{ courierMessage }}</p></div><button class="tracking-collapse" aria-label="Mostrar u ocultar detalles" @click="toggle"><ChevronUp :class="{ rotated: expanded }" :size="22" /></button></div><OrderProgressSegments :state="order.estado" /></section></Transition>
    <section class="tracking-sheet" :class="{ expanded }" @touchstart="down" @touchend="up"><button class="tracking-handle" aria-label="Expandir seguimiento" @click="toggle"><span /><ChevronUp :class="{ rotated: expanded }" :size="18" /></button><div v-if="!hasCourier" class="tracking-sheet__heading"><component :is="icon" :size="24" /><div><strong>{{ labels[order.estado] || order.estado }}</strong><p v-if="order.estado !== 'CANCELADO'">{{ messages[order.estado] || 'El restaurante está revisando tu pedido.' }}</p><p v-else>El pedido ya no continúa en seguimiento.</p></div></div><div v-if="!hasCourier && order.estado !== 'CANCELADO'"><OrderProgressSegments :state="order.estado" :expanded="expanded" /></div><div v-if="order.estado === 'CANCELADO'" class="tracking-cancellation-box"><strong>Información de cancelación</strong><span>Motivo: {{ cancellationReason(order.cancelaciones?.[0]?.motivo_codigo, order.cancelaciones?.[0]?.descripcion) }}</span><span>Pago: {{ order.metodo_pago === 'TARJETA_SIMULADA' ? 'Tarjeta' : 'Efectivo' }} · Total: ${{ Number(order.total || 0).toFixed(2) }}</span><span v-if="order.reembolsos?.[0]">Tipo: {{ order.reembolsos[0].automatico ? 'Automática' : 'Manual' }}</span><span v-if="order.reembolsos?.[0]">Solicitud: {{ formatRefundDate(order.reembolsos[0].created_at) }}</span><span v-if="order.reembolsos?.[0] && order.reembolsos[0].estado !== 'REVISION_MANUAL'">Resolución: {{ formatRefundDate(order.reembolsos[0].updated_at) }}</span><b>{{ refundLabel(order) }}</b></div><div v-if="order.estado === 'CANCELADO' && refundStage(order).length" class="tracking-refund-steps"><span v-for="(stage, index) in refundStage(order)" :key="stage" :class="{ active: index === refundStage(order).length - 1 }">{{ stage }}</span></div><div v-if="expanded || !hasCourier" class="tracking-detail"><p><b>{{ order.restaurantes?.nombre }}</b></p><div v-for="line in order.pedido_detalles || []" :key="line.id">{{ line.cantidad }} × {{ line.nombre_producto_snapshot }} <b>${{ Number(line.subtotal_linea).toFixed(2) }}</b></div><p><MapPin :size="15" /> {{ order.direcciones?.detalle || order.direccion_snapshot || 'Dirección registrada' }}</p><p v-if="hasCourier"><Truck :size="15" /> {{ courierName }}</p><strong>Total: ${{ Number(order.total).toFixed(2) }}</strong><button v-if="order.estado === 'ENTREGADO'" class="tracking-home-button" @click="emit('back')">Volver al inicio</button></div></section>
  </div>
</template>
